{
  "sessionId": "76a6ca47-ac39-4771-b462-7122245cb8f5:x:3",
  "name": "document",
  "definition": {
    "id": "document",
    "key": "document",
    "type": "compound",
    "description": "Context:\n\n- document (StudioDocument | null): the open document, kept current as the user or the assistant edits it.\n- blocks (Block[]): the parsed blocks of document.content; index-based ids regenerated on every parse.\n- renderCache (Record<string, RenderResult>): Mermaid render results keyed by diagram source, so unchanged diagrams are not rendered again.\n- selection (string | null): the selected block id, reported in the host context.\n- pending (PendingDocumentAction | null): the host action being executed: call id, the session it belongs to, the parsed action and the block its result names.\n- saveError (string | null): why the last save to IndexedDB failed.\n- retryCount (number): automatic retries started for this draft; resets on success, new edits, document changes or manual retry.",
    "initial": {
      "target": [
        "document.closed"
      ]
    },
    "states": {
      "closed": {
        "id": "document.closed",
        "key": "closed",
        "type": "atomic",
        "description": "No document is open; the centre pane shows the file list state.",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {
          "app.open": [
            {
              "eventType": "app.open",
              "description": "The app opens a document.",
              "source": "document.closed",
              "target": [
                "document.open"
              ],
              "actions": [
                "openDocument"
              ],
              "reenter": false
            }
          ]
        },
        "always": [],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [],
        "tags": []
      },
      "applying": {
        "id": "document.applying",
        "key": "applying",
        "type": "atomic",
        "description": "Transient: routes the pending host action.\n- invalid arguments: reply failed\n- create_document / open_document / rename_document: their own states\n- block edits: apply, then save and render\n- an edit without an open document: reply failed",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {},
        "always": [
          {
            "eventType": "",
            "description": "Arguments did not validate against the declared schema.",
            "source": "document.applying",
            "target": [
              "document.resuming"
            ],
            "guard": "pendingInvalid",
            "actions": [
              "replyPendingInvalid",
              "clearPending"
            ],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "create_document: write a new document that adopts the calling session.",
            "source": "document.applying",
            "target": [
              "document.creating"
            ],
            "guard": {
              "type": "pendingIs",
              "params": {
                "name": "create_document"
              }
            },
            "actions": [],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "open_document: find it by id or name.",
            "source": "document.applying",
            "target": [
              "document.finding"
            ],
            "guard": {
              "type": "pendingIs",
              "params": {
                "name": "open_document"
              }
            },
            "actions": [],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "Rename the open document, save, then reply.\n\nActions:\n- renameOpenFromPending: apply the requested name\n- resetRetries: start a fresh save budget",
            "source": "document.applying",
            "target": [
              "document.open.saving"
            ],
            "guard": "pendingRenamesOpen",
            "actions": [
              "renameOpenFromPending",
              "resetRetries"
            ],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "rename_document on another document: update it in the store.",
            "source": "document.applying",
            "target": [
              "document.renaming"
            ],
            "guard": {
              "type": "pendingIs",
              "params": {
                "name": "rename_document"
              }
            },
            "actions": [],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "Apply the block edit, then save and render.\n\nActions:\n- applyPendingEdit: update content, blocks and selection\n- resetRetries: start a fresh save budget",
            "source": "document.applying",
            "target": [
              "document.open.saving"
            ],
            "guard": "editApplies",
            "actions": [
              "applyPendingEdit",
              "resetRetries"
            ],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "A block edit that references an unknown block.",
            "source": "document.applying",
            "target": [
              "document.open.saving"
            ],
            "guard": "hasDocument",
            "actions": [
              "replyEditFailed",
              "clearPending"
            ],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "A block edit with no document open.",
            "source": "document.applying",
            "target": [
              "document.closed"
            ],
            "actions": [
              "replyNoDocument",
              "clearPending"
            ],
            "reenter": false
          }
        ],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [],
        "tags": []
      },
      "resuming": {
        "id": "document.resuming",
        "key": "resuming",
        "type": "atomic",
        "description": "Transient: return to the open document, or to closed.",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {},
        "always": [
          {
            "eventType": "",
            "description": "A document is open.",
            "source": "document.resuming",
            "target": [
              "document.open.saving"
            ],
            "guard": "hasDocument",
            "actions": [],
            "reenter": false
          },
          {
            "eventType": "",
            "description": "Nothing is open.",
            "source": "document.resuming",
            "target": [
              "document.closed"
            ],
            "actions": [],
            "reenter": false
          }
        ],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [],
        "tags": []
      },
      "creating": {
        "id": "document.creating",
        "key": "creating",
        "type": "atomic",
        "description": "Writing the new document to IndexedDB. Invokes creator.",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {
          "xstate.done.actor.0.document.creating": [
            {
              "eventType": "xstate.done.actor.0.document.creating",
              "description": "Created: open it, tell the app, then render and reply.",
              "source": "document.creating",
              "target": [
                "document.open.rendering"
              ],
              "actions": [
                "adoptDocument",
                "reportSaved",
                "reportOpened"
              ],
              "reenter": false
            }
          ],
          "xstate.error.actor.0.document.creating": [
            {
              "eventType": "xstate.error.actor.0.document.creating",
              "description": "The store refused the write; the assistant is told.",
              "source": "document.creating",
              "target": [
                "document.resuming"
              ],
              "actions": [
                "replyActorError",
                "clearPending"
              ],
              "reenter": false
            }
          ]
        },
        "always": [],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [
          {
            "id": "0.document.creating",
            "src": "creator"
          }
        ],
        "tags": []
      },
      "finding": {
        "id": "document.finding",
        "key": "finding",
        "type": "atomic",
        "description": "Looking the document up by id or name and moving the conversation to it. Invokes finder.",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {
          "xstate.done.actor.0.document.finding": [
            {
              "eventType": "xstate.done.actor.0.document.finding",
              "description": "Found: open it, tell the app, then render and reply.",
              "source": "document.finding",
              "target": [
                "document.open.rendering"
              ],
              "guard": "found",
              "actions": [
                "adoptDocument",
                "reportSaved",
                "reportOpened"
              ],
              "reenter": false
            },
            {
              "eventType": "xstate.done.actor.0.document.finding",
              "description": "No document matches.",
              "source": "document.finding",
              "target": [
                "document.resuming"
              ],
              "actions": [
                "replyNotFound",
                "clearPending"
              ],
              "reenter": false
            }
          ],
          "xstate.error.actor.0.document.finding": [
            {
              "eventType": "xstate.error.actor.0.document.finding",
              "description": "The store could not be read.",
              "source": "document.finding",
              "target": [
                "document.resuming"
              ],
              "actions": [
                "replyActorError",
                "clearPending"
              ],
              "reenter": false
            }
          ]
        },
        "always": [],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [
          {
            "id": "0.document.finding",
            "src": "finder"
          }
        ],
        "tags": []
      },
      "renaming": {
        "id": "document.renaming",
        "key": "renaming",
        "type": "atomic",
        "description": "Renaming a document that is not the open one. Invokes renamer.",
        "initial": {
          "target": []
        },
        "states": {},
        "on": {
          "xstate.done.actor.0.document.renaming": [
            {
              "eventType": "xstate.done.actor.0.document.renaming",
              "description": "Renamed: tell the app and reply.",
              "source": "document.renaming",
              "target": [
                "document.resuming"
              ],
              "guard": "found",
              "actions": [
                "reportSaved",
                "replyPendingSuccess",
                "clearPending"
              ],
              "reenter": false
            },
            {
              "eventType": "xstate.done.actor.0.document.renaming",
              "description": "No document with that id.",
              "source": "document.renaming",
              "target": [
                "document.resuming"
              ],
              "actions": [
                "replyNotFound",
                "clearPending"
              ],
              "reenter": false
            }
          ],
          "xstate.error.actor.0.document.renaming": [
            {
              "eventType": "xstate.error.actor.0.document.renaming",
              "description": "The store could not be written.",
              "source": "document.renaming",
              "target": [
                "document.resuming"
              ],
              "actions": [
                "replyActorError",
                "clearPending"
              ],
              "reenter": false
            }
          ]
        },
        "always": [],
        "after": [],
        "entry": [],
        "exit": [],
        "invoke": [
          {
            "id": "0.document.renaming",
            "src": "renamer"
          }
        ],
        "tags": []
      },
      "open": {
        "id": "document.open",
        "key": "open",
        "type": "compound",
        "description": "A document is open. Substates save and render; the pending host action is answered once rendering is done.",
        "initial": {
          "target": [
            "document.open.rendering"
          ]
        },
        "states": {
          "rendering": {
            "id": "document.open.rendering",
            "key": "rendering",
            "type": "atomic",
            "description": "Rendering the diagrams whose source is not cached. Invokes renderer.",
            "initial": {
              "target": []
            },
            "states": {},
            "on": {
              "xstate.done.actor.0.document.open.rendering": [
                {
                  "eventType": "xstate.done.actor.0.document.open.rendering",
                  "description": "The draft rendered but storage failed; begin bounded save recovery without declaring success.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.saveFailed"
                  ],
                  "guard": "hasSaveError",
                  "actions": [
                    "mergeRenders"
                  ],
                  "reenter": false
                },
                {
                  "eventType": "xstate.done.actor.0.document.open.rendering",
                  "description": "Rendered; a pending host action gets its result now.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.ready"
                  ],
                  "guard": "hasPending",
                  "actions": [
                    "mergeRenders",
                    "replyPendingSuccess",
                    "clearPending"
                  ],
                  "reenter": false
                },
                {
                  "eventType": "xstate.done.actor.0.document.open.rendering",
                  "description": "Rendered.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.ready"
                  ],
                  "actions": [
                    "mergeRenders"
                  ],
                  "reenter": false
                }
              ],
              "xstate.error.actor.0.document.open.rendering": [
                {
                  "eventType": "xstate.error.actor.0.document.open.rendering",
                  "description": "Record the renderer failure while the unsaved draft enters save recovery.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.saveFailed"
                  ],
                  "guard": "hasSaveError",
                  "actions": [
                    "markRenderFailure"
                  ],
                  "reenter": false
                },
                {
                  "eventType": "xstate.error.actor.0.document.open.rendering",
                  "description": "Mermaid itself failed; the affected diagrams are marked and the action still replies.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.ready"
                  ],
                  "guard": "hasPending",
                  "actions": [
                    "markRenderFailure",
                    "replyPendingSuccess",
                    "clearPending"
                  ],
                  "reenter": false
                },
                {
                  "eventType": "xstate.error.actor.0.document.open.rendering",
                  "description": "Mermaid itself failed; the affected diagrams are marked.",
                  "source": "document.open.rendering",
                  "target": [
                    "document.open.ready"
                  ],
                  "actions": [
                    "markRenderFailure"
                  ],
                  "reenter": false
                }
              ]
            },
            "always": [],
            "after": [],
            "entry": [],
            "exit": [],
            "invoke": [
              {
                "id": "0.document.open.rendering",
                "src": "renderer"
              }
            ],
            "tags": []
          },
          "saving": {
            "id": "document.open.saving",
            "key": "saving",
            "type": "compound",
            "description": "One IndexedDB write is in flight.\n- current: no newer draft\n- changed: keep edits in memory until this write settles, then save the latest draft",
            "initial": {
              "target": [
                "document.open.saving.current"
              ]
            },
            "states": {
              "current": {
                "id": "document.open.saving.current",
                "key": "current",
                "type": "atomic",
                "description": "The in-flight write contains the current draft.",
                "initial": {
                  "target": []
                },
                "states": {},
                "on": {},
                "always": [],
                "after": [],
                "entry": [],
                "exit": [],
                "invoke": [],
                "tags": []
              },
              "changed": {
                "id": "document.open.saving.changed",
                "key": "changed",
                "type": "atomic",
                "description": "The user edited during the write; its completion cannot mark the newer draft saved.",
                "initial": {
                  "target": []
                },
                "states": {},
                "on": {},
                "always": [],
                "after": [],
                "entry": [],
                "exit": [],
                "invoke": [],
                "tags": []
              }
            },
            "on": {
              "user.edit": [
                {
                  "eventType": "user.edit",
                  "description": "Keep the new draft while the existing write finishes.\n\nActions:\n- editContent: retain and reparse the latest draft\n- resetRetries: give the new draft a fresh retry budget",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.saving.changed"
                  ],
                  "actions": [
                    "editContent",
                    "resetRetries"
                  ],
                  "reenter": false
                }
              ],
              "user.rename": [
                {
                  "eventType": "user.rename",
                  "description": "Keep the new name while the existing write finishes.\n\nActions:\n- renameOpen: update the draft name\n- resetRetries: give the new draft a fresh retry budget",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.saving.changed"
                  ],
                  "actions": [
                    "renameOpen",
                    "resetRetries"
                  ],
                  "reenter": false
                }
              ],
              "xstate.done.actor.0.document.open.saving": [
                {
                  "eventType": "xstate.done.actor.0.document.open.saving",
                  "description": "An older draft committed; report that write and immediately save the newest draft in a new invocation.",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.saving"
                  ],
                  "guard": "saveHasNewerDraft",
                  "actions": [
                    "reportSaved"
                  ],
                  "reenter": true
                },
                {
                  "eventType": "xstate.done.actor.0.document.open.saving",
                  "description": "The current draft committed; render it.\n\nActions:\n- clearSaveError: clear the error only after storage succeeds\n- resetRetries: reset the automatic retry budget\n- reportSaved: notify the app of the persisted document",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.rendering"
                  ],
                  "actions": [
                    "clearSaveError",
                    "resetRetries",
                    "reportSaved"
                  ],
                  "reenter": false
                }
              ],
              "xstate.error.actor.0.document.open.saving": [
                {
                  "eventType": "xstate.error.actor.0.document.open.saving",
                  "description": "An older write failed; preserve the error and debounce the new draft without overlapping writes.",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.dirty"
                  ],
                  "guard": "saveHasNewerDraft",
                  "actions": [
                    "setSaveError"
                  ],
                  "reenter": false
                },
                {
                  "eventType": "xstate.error.actor.0.document.open.saving",
                  "description": "The current write failed; retain the draft and error, render, then enter bounded recovery.",
                  "source": "document.open.saving",
                  "target": [
                    "document.open.rendering"
                  ],
                  "actions": [
                    "setSaveError"
                  ],
                  "reenter": false
                }
              ]
            },
            "always": [],
            "after": [],
            "entry": [],
            "exit": [],
            "invoke": [
              {
                "id": "0.document.open.saving",
                "src": "saver"
              }
            ],
            "tags": []
          },
          "saveFailed": {
            "id": "document.open.saveFailed",
            "key": "saveFailed",
            "type": "compound",
            "description": "The rendered draft is still unsaved. Two automatic retries precede a manual fallback.",
            "initial": {
              "target": [
                "document.open.saveFailed.retrying"
              ]
            },
            "states": {
              "retrying": {
                "id": "document.open.saveFailed.retrying",
                "key": "retrying",
                "type": "atomic",
                "description": "Wait briefly before another save, unless the automatic retry budget is exhausted.",
                "initial": {
                  "target": []
                },
                "states": {},
                "on": {
                  "xstate.after.saveRetry.document.open.saveFailed.retrying": [
                    {
                      "eventType": "xstate.after.saveRetry.document.open.saveFailed.retrying",
                      "description": "Start the next bounded retry of the current draft.",
                      "source": "document.open.saveFailed.retrying",
                      "target": [
                        "document.open.saving"
                      ],
                      "actions": [
                        "incrementRetries"
                      ],
                      "reenter": false,
                      "delay": "saveRetry"
                    }
                  ]
                },
                "always": [
                  {
                    "eventType": "",
                    "description": "Storage retries exhausted during a host action; show the manual fallback.\n\nActions:\n- replySaveFailed: report the persistence failure once\n- clearPending: finish the host action",
                    "source": "document.open.saveFailed.retrying",
                    "target": [
                      "document.open.saveFailed.failed"
                    ],
                    "guard": "retriesExhaustedWithPending",
                    "actions": [
                      "replySaveFailed",
                      "clearPending"
                    ],
                    "reenter": false
                  },
                  {
                    "eventType": "",
                    "description": "Automatic retries exhausted; keep the draft for manual recovery.",
                    "source": "document.open.saveFailed.retrying",
                    "target": [
                      "document.open.saveFailed.failed"
                    ],
                    "guard": "retriesExhausted",
                    "actions": [],
                    "reenter": false
                  }
                ],
                "after": [
                  {
                    "eventType": "xstate.after.saveRetry.document.open.saveFailed.retrying",
                    "description": "Start the next bounded retry of the current draft.",
                    "source": "document.open.saveFailed.retrying",
                    "target": [
                      "document.open.saving"
                    ],
                    "actions": [
                      "incrementRetries"
                    ],
                    "reenter": false,
                    "delay": "saveRetry"
                  }
                ],
                "entry": [
                  {
                    "type": "xstate.raise"
                  }
                ],
                "exit": [
                  {
                    "type": "xstate.cancel"
                  }
                ],
                "invoke": [],
                "tags": []
              },
              "failed": {
                "id": "document.open.saveFailed.failed",
                "key": "failed",
                "type": "atomic",
                "description": "Automatic saves stopped. Keep the draft in this tab and let the user retry after fixing storage.",
                "initial": {
                  "target": []
                },
                "states": {},
                "on": {
                  "user.retrySave": [
                    {
                      "eventType": "user.retrySave",
                      "description": "The user retries the current draft with a fresh automatic retry budget.",
                      "source": "document.open.saveFailed.failed",
                      "target": [
                        "document.open.saving"
                      ],
                      "actions": [
                        "resetRetries"
                      ],
                      "reenter": false
                    }
                  ]
                },
                "always": [],
                "after": [],
                "entry": [],
                "exit": [],
                "invoke": [],
                "tags": []
              }
            },
            "on": {},
            "always": [],
            "after": [],
            "entry": [],
            "exit": [],
            "invoke": [],
            "tags": []
          },
          "ready": {
            "id": "document.open.ready",
            "key": "ready",
            "type": "atomic",
            "description": "Saved and rendered.",
            "initial": {
              "target": []
            },
            "states": {},
            "on": {},
            "always": [],
            "after": [],
            "entry": [],
            "exit": [],
            "invoke": [],
            "tags": []
          },
          "dirty": {
            "id": "document.open.dirty",
            "key": "dirty",
            "type": "atomic",
            "description": "Unsaved user edits; saves after a short pause in typing.",
            "initial": {
              "target": []
            },
            "states": {},
            "on": {
              "xstate.after.500.document.open.dirty": [
                {
                  "eventType": "xstate.after.500.document.open.dirty",
                  "description": "Typing paused.",
                  "source": "document.open.dirty",
                  "target": [
                    "document.open.saving"
                  ],
                  "actions": [],
                  "reenter": false,
                  "delay": 500
                }
              ]
            },
            "always": [],
            "after": [
              {
                "eventType": "xstate.after.500.document.open.dirty",
                "description": "Typing paused.",
                "source": "document.open.dirty",
                "target": [
                  "document.open.saving"
                ],
                "actions": [],
                "reenter": false,
                "delay": 500
              }
            ],
            "entry": [
              {
                "type": "xstate.raise"
              }
            ],
            "exit": [
              {
                "type": "xstate.cancel"
              }
            ],
            "invoke": [],
            "tags": []
          }
        },
        "on": {
          "app.open": [
            {
              "eventType": "app.open",
              "description": "The app switches to another document.",
              "source": "document.open",
              "target": [
                "document.open"
              ],
              "actions": [
                "openDocument"
              ],
              "reenter": true
            }
          ],
          "app.close": [
            {
              "eventType": "app.close",
              "description": "The app closed the document (deleted, or back to the list).",
              "source": "document.open",
              "target": [
                "document.closed"
              ],
              "actions": [
                "closeDocument"
              ],
              "reenter": false
            }
          ],
          "app.sync": [
            {
              "eventType": "app.sync",
              "description": "The document was renamed from the sidebar; keep the name current.",
              "source": "document.open",
              "actions": [
